<section id="inventory-view" hidden aria-labelledby="inventory-title">
    <div class="section-heading"><div><h1 id="inventory-title">Inventario</h1><p>Consulta tus existencias y conserva el motivo de cada cambio.</p></div><div class="form-actions catalog-actions inventory-heading-actions"><button id="inventory-alerts" class="secondary" data-icon="boxes-stacked" type="button" hidden>Alertas y reposición</button><button id="inventory-locations" class="secondary" type="button" hidden>Ubicaciones</button><button id="inventory-operations" class="secondary" type="button">Traspasos y mermas</button><button id="inventory-reload" class="secondary" type="button">Actualizar</button><button id="inventory-history" class="secondary" type="button">Historial</button></div></div>
    <p id="inventory-message" role="status" aria-live="polite"></p>
    <div id="inventory-stock-panel">
        <div class="filters inventory-filters"><div><label for="inventory-search">Buscar producto o SKU</label><input id="inventory-search" type="search" placeholder="Nombre, variante o código"></div><div><label for="inventory-location">Ubicación</label><select id="inventory-location"></select></div><div><label for="inventory-filter">Mostrar</label><select id="inventory-filter"><option value="active">Variantes activas</option><option value="low">Stock bajo o en mínimo</option><option value="negative">Existencias negativas</option><option value="all">Todas, incluidas inactivas</option></select></div></div>
        <p id="inventory-location-note" class="hint"></p><p id="inventory-count" class="hint" aria-live="polite"></p>
        <div class="table-scroll"><table class="inventory-table"><thead><tr><th scope="col">Producto y variante</th><th scope="col">SKU</th><th scope="col">Existencia</th><th scope="col">Mínimo</th><th scope="col">Situación</th><th scope="col"><span class="sr-only">Acciones</span></th></tr></thead><tbody id="inventory-rows"></tbody></table></div>
        <p id="inventory-empty" hidden>No hay variantes para estos filtros.</p>
        <p class="hint">Las cantidades están en la unidad base del producto. Las variantes sin movimientos aparecen con existencia cero.</p>
    </div>
    <section id="inventory-adjust-panel" class="catalog-editor" hidden aria-labelledby="adjust-title">
        <div class="section-heading"><div><h2 id="adjust-title">Registrar ajuste</h2><p id="adjust-summary" class="hint"></p></div><button id="adjust-back" type="button" class="secondary">Volver a existencias</button></div>
        <form id="inventory-adjust-form"><fieldset id="adjust-fields" class="adjust-fields"><div class="adjust-layout"><div>
            <label for="adjust-mode">Operación</label><select id="adjust-mode"><option value="inicial">Inventario inicial</option><option value="entrada">Entrada por ajuste</option><option value="salida">Salida por ajuste</option><option value="conteo">Conteo físico</option></select>
            <p id="adjust-mode-help" class="hint"></p>
            <label for="adjust-quantity" id="adjust-quantity-label">Cantidad</label><input id="adjust-quantity" type="number" min="0" max="9999999999.9999" step="1" required>
            <label for="adjust-reason">Motivo del movimiento</label><textarea id="adjust-reason" maxlength="300" rows="3" required placeholder="Ej. Conteo inicial de mercancía en tienda"></textarea>
        </div><aside class="adjust-preview" aria-label="Resultado del ajuste"><h3>Resultado previsto</h3><dl><div><dt>Existencia actual</dt><dd id="adjust-current"></dd></div><div><dt>Cambio</dt><dd id="adjust-change">—</dd></div><div><dt>Existencia resultante</dt><dd id="adjust-result">—</dd></div></dl><p id="adjust-warning" class="hint"></p><p class="hint">Se registrará quién hizo el ajuste, cuándo y por qué. El historial no se edita; un error se corrige con otro movimiento.</p></aside></div></fieldset>
            <p id="adjust-error" class="message" role="alert"></p><div class="form-actions"><button id="adjust-save" class="primary" type="submit">Registrar movimiento</button><button id="adjust-cancel" class="secondary" type="button">Cancelar</button></div>
        </form>
    </section>
    <section id="inventory-history-panel" hidden aria-labelledby="inventory-history-title"><div class="section-heading"><div><h2 id="inventory-history-title">Historial de movimientos</h2><p id="history-description" class="hint"></p></div><button id="history-back" type="button" class="secondary">Volver a existencias</button></div><div class="table-scroll"><table class="inventory-history-table"><thead><tr><th>Fecha</th><th>Producto / SKU</th><th>Ubicación</th><th>Movimiento</th><th>Cantidad</th><th>Usuario y motivo</th></tr></thead><tbody id="inventory-history-rows"></tbody></table></div><p id="history-empty" hidden>Todavía no hay movimientos para esta selección.</p><div class="form-actions"><button id="history-more" type="button" class="secondary" hidden>Cargar movimientos anteriores</button></div></section>
    <section id="warehouse-operation-panel" class="catalog-editor" hidden aria-labelledby="warehouse-operation-title"><div class="section-heading"><div><h2 id="warehouse-operation-title">Registrar operación</h2><p id="warehouse-operation-summary" class="hint"></p></div><button id="warehouse-operation-back" class="secondary" type="button">Volver a existencias</button></div><form id="warehouse-operation-form"><fieldset id="warehouse-operation-fields" class="adjust-fields"><div class="adjust-layout"><div>
        <div id="warehouse-destination-field"><label for="warehouse-destination">Ubicación de destino</label><select id="warehouse-destination"></select><p id="warehouse-destination-help" class="hint"></p></div>
        <label for="warehouse-quantity">Cantidad en unidad base</label><input id="warehouse-quantity" type="number" min="0.0001" max="9999999999.9999" step="0.0001" required>
        <label for="warehouse-reason">Motivo</label><textarea id="warehouse-reason" maxlength="300" rows="3" required placeholder="Ej. Reabastecimiento de tienda o producto roto"></textarea>
        <label class="check-label"><input id="warehouse-confirm" type="checkbox" required><span id="warehouse-confirm-label">Confirmo la operación</span></label>
    </div><aside class="adjust-preview"><h3>Resultado previsto</h3><dl><div><dt>Origen actual</dt><dd id="warehouse-origin-current"></dd></div><div><dt>Origen después</dt><dd id="warehouse-origin-next">—</dd></div><div id="warehouse-destination-preview"><dt>Destino después</dt><dd id="warehouse-destination-next">—</dd></div></dl><p id="warehouse-impact" class="hint"></p><p class="hint">Al confirmar se valida el saldo actual. No se permiten cantidades superiores a las existencias del origen.</p></aside></div></fieldset><p id="warehouse-error" class="message" role="alert"></p><div class="form-actions"><button id="warehouse-save" class="primary" type="submit">Registrar</button><button id="warehouse-cancel" class="secondary" type="button">Cancelar</button></div></form></section>
    <section id="warehouse-locations-panel" class="catalog-editor" hidden aria-labelledby="warehouse-locations-title"><div class="section-heading"><h2 id="warehouse-locations-title">Ubicaciones</h2><button id="warehouse-locations-back" class="secondary" type="button">Volver a existencias</button></div><div class="category-layout"><div class="table-scroll"><table><thead><tr><th>Nombre</th><th>Uso / estado</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody id="warehouse-location-rows"></tbody></table></div><form id="warehouse-location-form"><fieldset id="warehouse-location-fields" class="adjust-fields"><h3 id="warehouse-location-editor-title">Crear ubicación</h3><label for="warehouse-location-name">Nombre</label><input id="warehouse-location-name" name="nombre" maxlength="100" required placeholder="Ej. Tienda, Bodega o Dañados"><label for="warehouse-location-description">Descripción</label><textarea id="warehouse-location-description" name="descripcion" maxlength="300" rows="3"></textarea><label for="warehouse-location-use">Uso de la mercancía</label><select id="warehouse-location-use" name="disponible_venta"><option value="1">Disponible para venta</option><option value="0">Resguardo (no disponible para venta)</option></select><p class="hint">Usa Resguardo para productos dañados, en revisión o pendientes de devolución. Siguen en inventario físico.</p><label for="warehouse-location-active">Estado</label><select id="warehouse-location-active" name="activo"><option value="1">Activa</option><option value="0">Inactiva</option></select><p class="hint">Para desactivar una ubicación, primero debe quedar sin existencias.</p></fieldset><p id="warehouse-location-error" class="message" role="alert"></p><div class="form-actions"><button id="warehouse-location-save" class="primary" type="submit">Guardar ubicación</button><button id="warehouse-location-new" class="secondary" type="button">Nueva</button></div></form></div></section>
    <section id="warehouse-ledger-panel" hidden aria-labelledby="warehouse-ledger-title"><div class="section-heading"><div><h2 id="warehouse-ledger-title">Traspasos y mermas</h2><p id="warehouse-ledger-description" class="hint"></p></div><button id="warehouse-ledger-back" class="secondary" type="button">Volver a existencias</button></div><p class="hint">Los documentos confirmados se conservan. Un traspaso mueve mercancía; una merma registra su baja definitiva.</p><div class="table-scroll"><table class="warehouse-ledger-table"><thead><tr><th>Folio / fecha</th><th>Operación</th><th>Producto / SKU</th><th>Origen → destino</th><th>Cantidad</th><th>Usuario y motivo</th></tr></thead><tbody id="warehouse-ledger-rows"></tbody></table></div><p id="warehouse-ledger-empty" hidden>No hay traspasos ni mermas para esta ubicación. Regístralos desde las acciones de cada variante en Existencias.</p><div class="form-actions"><button id="warehouse-ledger-more" class="secondary" type="button" hidden>Cargar anteriores</button></div></section>
    <section id="inventory-alerts-panel" hidden aria-labelledby="stock-alert-title">
        <div class="section-heading"><div><h2 id="stock-alert-title">Alertas y reposición</h2><p id="stock-alert-intro" class="hint">Se avisa al llegar al mínimo. Revisa qué falta en cada ubicación antes de preparar tus compras.</p></div><button id="stock-alert-back" class="secondary" data-icon="arrow-left" type="button">Volver a existencias</button></div>
        <p id="stock-alert-message" role="status" aria-live="polite"></p>
        <div class="form-actions stock-alert-modes"><button id="stock-alert-mode" class="primary" type="button" aria-pressed="true">Por reponer</button><button id="stock-minimum-mode" class="secondary" type="button" aria-pressed="false" hidden>Configurar mínimos</button></div>
        <form id="stock-alert-filters" class="filters stock-alert-filters"><div><label for="stock-alert-search">Buscar producto o SKU</label><input id="stock-alert-search" type="search" maxlength="150" placeholder="Ej. Termo de 750 ml"></div><div><label for="stock-alert-location">Ubicación</label><select id="stock-alert-location"><option value="">Todas las ubicaciones</option></select></div><div id="stock-alert-state-field"><label for="stock-alert-state">Situación</label><select id="stock-alert-state"><option value="">Todas las alertas</option><option value="agotado">Agotado</option><option value="bajo">Bajo mínimo</option><option value="minimo">En mínimo</option><option value="negativo">Existencia negativa</option></select></div><button id="stock-alert-search-button" class="secondary" data-icon="magnifying-glass" type="submit">Consultar</button></form>
        <p class="hint">Solo ubicaciones activas disponibles para venta. El mínimo general del catálogo se usa hasta que definas uno para esa ubicación. Un mínimo de cero desactiva su alerta.</p>
        <div class="stock-alert-list-heading"><p id="stock-alert-count" class="hint" aria-live="polite"></p><button id="stock-alert-export" class="secondary" data-icon="floppy-disk" type="button">Descargar lista para compras (CSV)</button></div>
        <p class="hint stock-alert-scroll-help">Desliza la tabla hacia los lados para ver todas las columnas.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Existencias y mínimos por ubicación"><table class="stock-alert-table"><thead><tr><th>Producto / SKU</th><th>Ubicación</th><th>Existencia</th><th>Mínimo</th><th>Faltante para mínimo</th><th>Situación</th><th id="stock-alert-actions-heading" hidden>Acciones</th></tr></thead><tbody id="stock-alert-rows"></tbody></table></div>
        <p id="stock-alert-empty" hidden>No hay productos por reponer para estos filtros.</p><p id="stock-alert-list-help" class="hint">El faltante es lo necesario para alcanzar el mínimo, no una compra automática. Al estar justo en el mínimo puede ser cero. Primero considera si puedes traspasar desde otra ubicación. Si hay existencias negativas, revisa el conteo.</p>
        <div class="form-actions"><button id="stock-alert-prev" class="secondary" type="button" disabled>Anterior</button><span id="stock-alert-page" class="hint"></span><button id="stock-alert-next" class="secondary" type="button" disabled>Siguiente</button></div>
    </section>
    <section id="inventory-minimum-panel" class="catalog-editor stock-minimum-editor" hidden aria-labelledby="stock-minimum-title"><h2 id="stock-minimum-title">Mínimo de inventario</h2><p id="stock-minimum-context"></p><p id="stock-minimum-stock" class="hint"></p><form id="stock-minimum-form"><fieldset id="stock-minimum-fields" class="adjust-fields"><label class="check-label"><input id="stock-minimum-default" type="checkbox"> Usar el mínimo general del catálogo</label><p id="stock-minimum-general" class="hint"></p><label for="stock-minimum-value">Mínimo para esta ubicación</label><input id="stock-minimum-value" type="number" min="0" max="9999999999.9999" step="1" required><p class="hint">Un mínimo de cero desactiva la alerta en esta ubicación. Guardar este valor no cambia las existencias.</p></fieldset><p id="stock-minimum-error" class="message" role="alert"></p><div class="form-actions"><button id="stock-minimum-save" class="primary" data-icon="floppy-disk" type="submit">Guardar mínimo</button><button id="stock-minimum-cancel" class="secondary" type="button">Cancelar</button></div></form></section>
</section>
